module elasticArbiter_1(
  input        clock,
               reset,
  input  [1:0] io_sources_0_bits_id,
               io_sources_0_bits_resp,
  input        io_sources_0_valid,
  output       io_sources_0_ready,
  input  [1:0] io_sources_1_bits_id,
               io_sources_1_bits_resp,
